from collections import Counter

def transform(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    def bar(rows):
        for i,row in rows:
            c=Counter(x for x in row if x!=bg)
            if c and c.most_common(1)[0][1]>1:
                col=c.most_common(1)[0][0]
                js=set(k for k,x in enumerate(row) if x==col)
                return (i,js[0] if False else min(js),js)
    t=bar(list(enumerate(g))); b=bar(list(enumerate(g))[::-1]); b=(h-1-b[0],b[1],b[2])
    barcells={(t[0],j) for j in t[2]}|{(b[0],j) for j in b[2]}
    out=[row[:] for row in g]
    pix=[(i,j) for i in range(h) for j in range(w) if (i,j) not in barcells and g[i][j]!=bg]
    for pi,pj in pix:
        pc=g[pi][pj]
        for i in range(t[0]+1,pi):
            out[i][pj]=pc
        m=b[1]+(pj-t[1])
        for i in range(b[0]):
            if (i,m) not in barcells: out[i][m]=pc
        out[pi][pj]=4
    return out

